import React from 'react';
import { BrowserRouter as Router, Routes, Route, Link, Navigate } from 'react-router-dom';
import { useAuth } from './hooks/useAuth'; // Your authentication hook
import Dashboard from './pages/Dashboard'; // General user dashboard
import AddRestaurant from './components/restaurant/AddRestaurant';
import EditRestaurant from './components/restaurant/EditRestaurant';
import RestaurantDashboard from './components/restaurant/RestaurantDashboard';
import AddMenuItem from './components/restaurant/AddMenuItem';
import EditMenuItem from './components/restaurant/EditMenuItem';
import OrderHistory from './components/order/OrderHistory';
import OrderDetails from './components/order/OrderDetails';
// ... other components

function App() {
  const { auth, user } = useAuth();

  return (
    <Router>
      <div>
        <nav>
          <ul>
            <li><Link to="/">Home</Link></li>
            {auth && <li><Link to="/dashboard">Dashboard</Link></li>}

            {/* Restaurant Owner Link */}
            {auth && user?.role === 'restaurant' && (
              <li><Link to="/restaurant/dashboard">Restaurant Management</Link></li>
            )}

            {/* Customer Links */}
            {auth && user?.role === 'customer' && (
              <li><Link to="/orders/history">Order History</Link></li>
            )}

            {!auth && <li><Link to="/login">Login</Link></li>}
            {auth && <li><button onClick={() => /* your logout function */ null}>Logout</button></li>}
          </ul>
        </nav>

        <Routes>
          <Route path="/" element={<div>Home Page</div>} />
          <Route path="/login" element={<div>Login Page</div>} />
          <Route path="/dashboard" element={auth ? <Dashboard /> : <Navigate to="/login" />} />

          {/* Restaurant Owner Routes */}
          <Route path="/restaurant/add" element={auth && user?.role === 'restaurant' ? <AddRestaurant /> : <Navigate to="/login" />} />
          <Route path="/restaurant/edit/:id" element={auth && user?.role === 'restaurant' ? <EditRestaurant /> : <Navigate to="/login" />} />
          <Route path="/restaurant/dashboard" element={auth && user?.role === 'restaurant' ? <RestaurantDashboard /> : <Navigate to="/login" />} />
          <Route path="/restaurant/menu/add" element={auth && user?.role === 'restaurant' ? <AddMenuItem /> : <Navigate to="/login" />} />
          <Route path="/restaurant/menu/edit/:id" element={auth && user?.role === 'restaurant' ? <EditMenuItem /> : <Navigate to="/login" />} />

          {/* Order Management Routes (Customer) */}
          <Route path="/orders/history" element={auth && user?.role === 'customer' ? <OrderHistory /> : <Navigate to="/login" />} />
          <Route path="/order/:id" element={auth ? <OrderDetails /> : <Navigate to="/login" />} /> {/* Accessible to logged-in users to see order details */}

          {/* ... other routes (e.g., for placing orders from a restaurant's menu) */}
        </Routes>
      </div>
    </Router>
  );
}

export default App;
